const $ = (s) => document.querySelector(s);
let token = sessionStorage.getItem('monitor_token') || '';
let paused = false, rangeSec = 300, procMode = 'cpu', lastSnapshot = null;
const history = [];
const maxPoints = 86400;

const fmtBytes = (n) => { if (!Number.isFinite(n)) return '—'; const u=['B','KB','MB','GB','TB']; let i=0; while(n>=1024&&i<u.length-1){n/=1024;i++} return `${n.toFixed(i>1?1:0)} ${u[i]}` };
const fmtRate = (n) => `${fmtBytes((n||0)/8)}/s`;
const pct = (n) => n == null ? '—' : `${n.toFixed(1)}%`;
const authHeaders = () => ({Authorization:`Bearer ${token}`});

async function api(path){ const r=await fetch(path,{headers:authHeaders()}); if(r.status===401){showAuth();throw new Error('unauthorized')} if(!r.ok)throw new Error(`${r.status}`); return r.json() }
function showAuth(){ $('#auth').classList.remove('hidden') }
$('#auth-form').addEventListener('submit',async e=>{e.preventDefault();token=$('#token').value;sessionStorage.setItem('monitor_token',token);try{await bootstrap();$('#auth').classList.add('hidden')}catch{}});

function push(v){lastSnapshot=v;history.push(v);const cutoff=Date.now()-rangeSec*1000;while(history.length&&new Date(history[0].timestamp).getTime()<cutoff)history.shift();if(history.length>maxPoints)history.splice(0,history.length-maxPoints);if(!paused)render(v)}
function render(v){
 $('#cpu').textContent=pct(v.cpu.total_pct);$('#cpu-now').textContent=pct(v.cpu.total_pct);$('#cpu-meta').textContent=`${v.cpu.per_core_pct.length} cores · ${v.cpu.load_1.toFixed(2)} load`;
 $('#mem').textContent=pct(v.memory.used_pct);$('#mem-now').textContent=`${fmtBytes(v.memory.used_bytes)} / ${fmtBytes(v.memory.total_bytes)}`;$('#mem-meta').textContent=`${fmtBytes(v.memory.available_bytes)} available`;
 const rx=v.network.reduce((a,x)=>a+(x.rx_bps||0),0),tx=v.network.reduce((a,x)=>a+(x.tx_bps||0),0);$('#net').textContent=fmtRate(rx);$('#net-meta').textContent=`RX ${fmtRate(rx)} · TX ${fmtRate(tx)}`;$('#net-now').textContent=`↓ ${fmtRate(rx)}  ↑ ${fmtRate(tx)}`;
 $('#conn').textContent=v.established_connections;const dr=v.disk_io.reduce((a,x)=>a+(x.read_bps||0),0),dw=v.disk_io.reduce((a,x)=>a+(x.write_bps||0),0);$('#disk-now').textContent=`R ${fmtBytes(dr)}/s · W ${fmtBytes(dw)}/s`;
 renderMounts(v.mounts);renderProcesses(v);drawAll();
}
function renderMounts(rows){$('#mounts').innerHTML=rows.map(x=>`<tr><td>${esc(x.mount_point)}<div class="bar"><i style="width:${Math.min(100,x.used_pct)}%"></i></div></td><td>${esc(x.fs_type)}</td><td>${pct(x.used_pct)} · ${fmtBytes(x.used_bytes)} / ${fmtBytes(x.total_bytes)}</td><td>${x.inodes_total?pct(x.inodes_used*100/x.inodes_total):'—'}</td></tr>`).join('')}
function renderProcesses(v){const rows=procMode==='cpu'?v.top_cpu:v.top_ram;$('#proc-count').textContent=`${v.process_count} total`;$('#processes').innerHTML=rows.map(x=>`<tr><td>${x.pid}</td><td>${esc(x.name)}</td><td>${pct(x.cpu_pct)}</td><td>${fmtBytes(x.rss_bytes)}</td><td>${x.threads}</td></tr>`).join('')}
function esc(s){const d=document.createElement('div');d.textContent=s;return d.innerHTML}

function draw(canvas, series, maxY, formatter){const c=$(canvas),r=c.getBoundingClientRect(),dpr=devicePixelRatio||1;c.width=Math.max(1,r.width*dpr);c.height=Math.max(1,r.height*dpr);const x=c.getContext('2d');x.scale(dpr,dpr);const w=r.width,h=r.height,p=24;x.clearRect(0,0,w,h);x.strokeStyle=getComputedStyle(document.body).getPropertyValue('--line');x.lineWidth=1;for(let i=0;i<5;i++){let yy=p+(h-2*p)*i/4;x.beginPath();x.moveTo(p,yy);x.lineTo(w-p,yy);x.stroke()}const vals=series.flatMap(s=>s.values.filter(Number.isFinite));const top=maxY||Math.max(1,...vals)*1.1;series.forEach((s,si)=>{x.strokeStyle=si===0?'#8da2ff':si===1?'#6ee7b7':'#fbbf24';x.lineWidth=1.5;x.beginPath();s.values.forEach((v,i)=>{if(!Number.isFinite(v))return;const xx=p+(w-2*p)*(i/Math.max(1,s.values.length-1));const yy=h-p-(h-2*p)*(v/top);if(i===0)x.moveTo(xx,yy);else x.lineTo(xx,yy)});x.stroke()});c.onmousemove=e=>{if(!history.length)return;const i=Math.round((e.offsetX-p)/(w-2*p)*(history.length-1));if(i<0||i>=history.length)return;const t=history[i];const tip=$('#tooltip');tip.textContent=`${new Date(t.timestamp).toLocaleTimeString()} · ${formatter(t)}`;tip.style.left=`${e.clientX+12}px`;tip.style.top=`${e.clientY+12}px`;tip.classList.remove('hidden')};c.onmouseleave=()=>$('#tooltip').classList.add('hidden')}
function drawAll(){draw('#cpu-chart',[{values:history.map(x=>x.cpu.total_pct)}],100,x=>`CPU ${pct(x.cpu.total_pct)}`);draw('#mem-chart',[{values:history.map(x=>x.memory.used_pct)},{values:history.map(x=>x.memory.swap_total_bytes?x.memory.swap_used_bytes*100/x.memory.swap_total_bytes:0)}],100,x=>`RAM ${pct(x.memory.used_pct)}`);draw('#net-chart',[{values:history.map(x=>x.network.reduce((a,n)=>a+(n.rx_bps||0),0))},{values:history.map(x=>x.network.reduce((a,n)=>a+(n.tx_bps||0),0))}],0,x=>`RX ${fmtRate(x.network.reduce((a,n)=>a+(n.rx_bps||0),0))}`);draw('#disk-chart',[{values:history.map(x=>x.disk_io.reduce((a,n)=>a+(n.read_bps||0),0))},{values:history.map(x=>x.disk_io.reduce((a,n)=>a+(n.write_bps||0),0))}],0,x=>`R ${fmtBytes(x.disk_io.reduce((a,n)=>a+(n.read_bps||0),0))}/s`)}

async function loadHistory(){const to=Math.floor(Date.now()/1000),from=to-rangeSec;const step=rangeSec>86400?60:rangeSec>3600?5:1;const j=await api(`/api/v1/metrics?from=${from}&to=${to}&step=${step}s`);history.splice(0,history.length,...j.metrics);if(history.length)render(history[history.length-1])}
async function system(){const s=await api('/api/v1/system');$('#hostname').textContent=s.hostname;$('#uptime').textContent=`uptime ${Math.floor(s.uptime_sec/3600)}h`;}
async function alerts(){const j=await api('/api/v1/alerts');$('#alerts').innerHTML=j.alerts.length?j.alerts.slice().reverse().slice(0,30).map(a=>`<div class="alert"><span class="${a.state}">${a.state}</span><b>${a.rule}</b><span>${esc(a.message)}</span><time>${new Date(a.updated_at).toLocaleString()}</time></div>`).join(''):'<span class="muted">No alert events</span>'}
async function stream(){while(token){try{const r=await fetch('/api/v1/ws',{headers:authHeaders()});if(r.status===401){showAuth();return}if(!r.ok)throw Error();$('#status').textContent='live';$('#status').className='badge good';const reader=r.body.getReader(),dec=new TextDecoder();let buf='';for(;;){const {done,value}=await reader.read();if(done)break;buf+=dec.decode(value,{stream:true});let cut;while((cut=buf.indexOf('\n\n'))>=0){const msg=buf.slice(0,cut);buf=buf.slice(cut+2);const line=msg.split('\n').find(x=>x.startsWith('data: '));if(line){const v=JSON.parse(line.slice(6));push(v);$('#load').textContent=`load ${v.cpu.load_1.toFixed(2)}`}}}}catch{}$('#status').textContent='reconnecting';$('#status').className='badge warn';await new Promise(r=>setTimeout(r,1500))}}
async function bootstrap(){await system();await loadHistory();await alerts();stream()}

document.querySelectorAll('[data-range]').forEach(b=>b.onclick=async()=>{document.querySelectorAll('[data-range]').forEach(x=>x.classList.remove('active'));b.classList.add('active');rangeSec=Number(b.dataset.range);await loadHistory()});$('#pause').onclick=()=>{paused=!paused;$('#pause').textContent=paused?'Resume':'Pause';if(!paused&&lastSnapshot)render(lastSnapshot)};$('#theme').onclick=()=>document.body.classList.toggle('light');$('#cpu-tab').onclick=()=>{procMode='cpu';$('#cpu-tab').classList.add('active');$('#ram-tab').classList.remove('active');if(lastSnapshot)renderProcesses(lastSnapshot)};$('#ram-tab').onclick=()=>{procMode='ram';$('#ram-tab').classList.add('active');$('#cpu-tab').classList.remove('active');if(lastSnapshot)renderProcesses(lastSnapshot)};$('#refresh-alerts').onclick=alerts;window.addEventListener('resize',()=>lastSnapshot&&drawAll());
if(token)bootstrap().catch(showAuth);else showAuth();
